const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No video with qc_passed_at set found for this topic. Run Phase 5 (phase5-qc.json) and get an overall_pass first.');
}
const video = items[0].json;
return [{ json: { id: video.id, channel_id: video.channel_id, script_id: video.script_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No "final" script found for this topic — Phase 2 must have completed with a Critic pass.');
}
return [{ json: { script_content: items[0].json.content } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found for this topic — data inconsistency, check the topics/channels tables.');
}
const channel = items[0].json;
return [{ json: { name: channel.name, niche: channel.niche, brand_voice: channel.brand_voice } }];

const script = $('Pick Script Row').first().json.script_content;
const headerRe = /\[([A-Z]+)\]\s*\(~?(\d+)s[^)]*\)/g;
const headers = [];
let m;
while ((m = headerRe.exec(script)) !== null) {
  headers.push({ label: m[1], duration: parseInt(m[2], 10), headerEnd: m.index + m[0].length, headerStart: m.index });
}
if (headers.length === 0) {
  throw new Error('Could not parse any [BEAT] (~Ns) headers out of the final script — the Shorts Factory needs the timestamped beat structure Phase 2 writes.');
}
let cursor = 0;
const beats = headers.map((h, i) => {
  const textEnd = i + 1 < headers.length ? headers[i + 1].headerStart : script.length;
  const text = script.slice(h.headerEnd, textEnd).trim();
  const start = cursor;
  const end = cursor + h.duration;
  cursor = end;
  return { beat: h.label, start_seconds: start, end_seconds: end, text };
});
return [{ json: { transcript: beats } }];

const script = $('Pick Script Row').first().json.script_content;
const transcript = $('Build Timestamped Transcript').first().json.transcript;
const channel = $('Pick Channel Info Row').first().json;

const system = `You are the Shorts Factory agent. Take one finished long-form video and produce
3-8 short-form scripts — you do not simply crop the video.

Channel: ${channel.name} (niche: ${channel.niche})
Brand voice: ${channel.brand_voice}

Source script: ${script}

Transcript with timestamps (approximate, derived from the script's own beat
durations — treat second-level precision loosely): ${JSON.stringify(transcript, null, 2)}

For each Short:
1. Identify one strong, self-contained moment (a surprising fact, a sharp turn, a
   strong explanation) that works with zero context from the rest of the video.
2. Write a new hook for the first 2 seconds — the long-form hook won't work
   vertically, it needs to be faster and punchier.
3. Write the narration (20-60 seconds) — can reuse phrasing from the source but
   must stand alone.
4. Note a CTA pointing to the full video, adapted to channel voice.

Label each Short with its source timestamp range, so video assembly knows which
footage to reuse versus what needs new vertical-native shots.

--- RESPONSE FORMAT ---

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "shorts": [
    {
      "title": string,
      "hook": string,
      "narration": string,
      "cta": string,
      "source_start_seconds": number,
      "source_end_seconds": number
    }
  ]
}
Include between 3 and 8 items in the "shorts" array.`;

return [{ json: { system } }];

const raw = $input.first().json["Claude's Shorts JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
const valid = parsed && Array.isArray(parsed.shorts) && parsed.shorts.length >= 3 && parsed.shorts.length <= 8 &&
  parsed.shorts.every(s => s.title && s.hook && s.narration);
if (parseError || !valid) {
  throw new Error('Could not parse a valid Shorts JSON (needs a "shorts" array of 3-8 items, each with title/hook/narration). Paste error: ' + (parseError || 'missing/malformed fields or wrong array length'));
}

const videoId = $('Pick Video Row').first().json.id;
const rows = parsed.shorts.map(s => ({
  parent_video_id: videoId,
  title: s.title,
  hook: s.hook,
  narration: s.narration,
  cta: s.cta || null,
  source_start_seconds: typeof s.source_start_seconds === 'number' ? s.source_start_seconds : null,
  source_end_seconds: typeof s.source_end_seconds === 'number' ? s.source_end_seconds : null,
  storage_url: null,
  status: 'pending'
}));

return [{ json: { rows, count: rows.length } }];

const count = $('Parse Shorts JSON').first().json.count;
return [{ json: {
  result: `${count} Shorts scripts saved to the shorts table (status: pending).`,
  topic: $('Pick Topic Row').first().json.topic_title,
  video_id: $('Pick Video Row').first().json.id,
  shorts_count: count
} }];
